import{bQ as a,aL as t,u as o,G as i}from"./chunks/framework.DpUpLuct.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1790485184000}'),r={name:"guide/faq.md"};function d(n,e,s,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="提示-invalid-input-或-403-是什么意思" tabindex="-1">提示 <code>Invalid input.</code> 或 403 是什么意思？ <a class="header-anchor" href="#提示-invalid-input-或-403-是什么意思" aria-label="Permalink to &quot;提示 `Invalid input.` 或 403 是什么意思？&quot;">​</a></h2><p>说明请求的路径不是一个可识别的 GitHub 链接。请确认链接属于 release、archive、blob/raw、gist 或 tags 等受支持的类型。如果配置了白名单，未命中的链接也会被拒绝。</p><h2 id="为什么不支持直接加速项目文件夹" tabindex="-1">为什么不支持直接加速项目文件夹？ <a class="header-anchor" href="#为什么不支持直接加速项目文件夹" aria-label="Permalink to &quot;为什么不支持直接加速项目文件夹？&quot;">​</a></h2><p>GitHub 的网页文件树（仓库首页）是动态页面，并非静态资源，代理无法像下载文件那样直接转发。请进入到具体文件后再复制链接。</p><h2 id="下载链接会跳转到-jsdelivr-吗" tabindex="-1">下载链接会跳转到 jsDelivr 吗？ <a class="header-anchor" href="#下载链接会跳转到-jsdelivr-吗" aria-label="Permalink to &quot;下载链接会跳转到 jsDelivr 吗？&quot;">​</a></h2><p>只有在开启 <code>Config.jsdelivr = 1</code>（或命中了 passby 规则）时，<code>blob</code> 与 <code>raw</code> 链接才会 302 到 jsDelivr。默认情况下，<code>blob</code> 会被转换为 <code>raw</code> 后由服务转发。</p><h2 id="通过加速域名访问时-页面样式或资源加载失败" tabindex="-1">通过加速域名访问时，页面样式或资源加载失败？ <a class="header-anchor" href="#通过加速域名访问时-页面样式或资源加载失败" aria-label="Permalink to &quot;通过加速域名访问时，页面样式或资源加载失败？&quot;">​</a></h2><p>请确认 <code>ASSET_URL</code> 指向了正确的站点地址，并且服务端会处理站点子路径前缀。本仓库中的 <code>index.js</code> 与 <code>app/main.py</code> 已经内置了前缀归一化逻辑，直接使用即可。</p><h2 id="可以加速私有仓库吗" tabindex="-1">可以加速私有仓库吗？ <a class="header-anchor" href="#可以加速私有仓库吗" aria-label="Permalink to &quot;可以加速私有仓库吗？&quot;">​</a></h2><p>可以。在链接中内嵌用户名与 Token 即可，例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://user:TOKEN@&lt;你的加速域名&gt;/https://github.com/user/private-repo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>请妥善保管 Token，使用完后及时撤销。</p><h2 id="免费额度够用吗" tabindex="-1">免费额度够用吗？ <a class="header-anchor" href="#免费额度够用吗" aria-label="Permalink to &quot;免费额度够用吗？&quot;">​</a></h2><p>Cloudflare Workers 免费版每天有 10 万次请求，并有每分钟 1000 次请求的限制。如果不够用，可以升级付费版本（每月 1000 万次请求）。如需大规模使用，建议自行部署。</p><h2 id="python-版本启动时报错无法访问-github-io" tabindex="-1">Python 版本启动时报错无法访问 github.io？ <a class="header-anchor" href="#python-版本启动时报错无法访问-github-io" aria-label="Permalink to &quot;Python 版本启动时报错无法访问 github.io？&quot;">​</a></h2><p>Python 版本会在启动时拉取 <code>ASSET_URL</code> 页面内容。如果服务器网络无法访问 <code>github.io</code>，请把 <code>ASSET_URL</code> 换成可访问的静态地址，或改为在本地托管静态文件。</p>',17)])])}const b=a(r,[["render",d]]);export{u as __pageData,b as default};
